import base64
import os

from playwright.sync_api import TimeoutError as PlaywrightTimeoutError, sync_playwright


BASE_URL = os.environ.get("FGO_E2E_URL", "http://127.0.0.1:5190")
PIXEL = base64.b64decode(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII="
)

AUDIO = base64.b64decode(
    ""
)



with sync_playwright() as playwright:
    browser = playwright.chromium.launch(headless=True)
    page = browser.new_page(viewport={"width": 2048, "height": 1114})
    page_errors = []
    page.on("pageerror", lambda error: page_errors.append(str(error)))

    def _cdn_mock(route):
        # Deterministic offline assets. Script text must be real (the parser
        # needs it) — fetch it through Python, which retains network access.
        # Audio becomes silence, everything else a 1px placeholder image.
        url = route.request.url
        if url.endswith(".txt") and "/Script/" in url:
            import urllib.request

            try:
                data = urllib.request.urlopen(url, timeout=20).read()
                route.fulfill(
                    status=200,
                    content_type="text/plain; charset=utf-8",
                    body=data,
                )
            except Exception:
                route.fulfill(status=404, body="")
            return
        if url.endswith(".mp3") or "/Audio/" in url or url.endswith(".wav"):
            route.fulfill(status=200, content_type="audio/wav", body=AUDIO)
        else:
            route.fulfill(status=200, content_type="image/png", body=PIXEL)

    page.route(
        "https://static.atlasacademy.io/**",
        _cdn_mock,
    )
    page.goto(BASE_URL, wait_until="domcontentloaded", timeout=60000)
    try:
        page.wait_for_load_state("networkidle", timeout=15000)
    except PlaywrightTimeoutError:
        pass

    page.locator(".region-select select").select_option("JP")
    page.evaluate(
        "localStorage.setItem('fgo-reader-settings', JSON.stringify({reduceMotion: true}))"
    )
    direct_input = page.locator(".direct-script input")
    direct_input.fill("0500010211")
    direct_input.press("Enter")

    page.locator(".reader-loading").wait_for(state="hidden", timeout=60000)
    scene = page.locator(".scene-image:not(.scene-image-previous)")
    scene.wait_for(timeout=30000)
    page.wait_for_function(
        "document.querySelector('.scene-image:not(.scene-image-previous)')?.complete && "
        "document.querySelector('.scene-image:not(.scene-image-previous)')?.naturalWidth > 0",
        timeout=30000,
    )
    # Let the scene-appear animation (420ms, may restart on scene change) and
    # the world-layer camera transition (180ms) settle before measuring.
    page.wait_for_timeout(1500)

    stage_box = page.locator(".reader-stage").bounding_box()
    assert stage_box is not None
    assert stage_box["x"] == 0 and stage_box["y"] == 0
    assert stage_box["width"] == 2048 and stage_box["height"] == 1114
    scene_metrics = scene.evaluate(
        """image => {
          const style = getComputedStyle(image);
          const box = image.getBoundingClientRect();
          return {
            objectFit: style.objectFit,
            width: box.width,
            height: box.height,
            left: box.left,
            top: box.top,
          };
        }"""
    )
    # The script applies [cameraMove 0 0,0 1.01] before the first scene; the
    # camera zoom composes with the letterbox cover geometry.
    camera_scale = float(page.locator(".world-layer").evaluate(
        "element => getComputedStyle(element).getPropertyValue('--camera-scale')"
    ) or "1")
    expected_width = max(stage_box["width"], stage_box["height"] * 1024 / 576) * camera_scale
    expected_height = expected_width * 626 / 1024
    assert scene_metrics["objectFit"] == "fill"
    assert abs(scene_metrics["width"] - expected_width) < 0.5
    assert abs(scene_metrics["height"] - expected_height) < 0.5
    assert abs(scene_metrics["left"] - (stage_box["width"] - expected_width) / 2) < 0.5
    assert abs(scene_metrics["top"] - (stage_box["height"] - expected_height) / 2) < 0.5
    assert not page_errors, f"Page errors: {page_errors}"
    browser.close()
